import numpy as np
from math import cos,sin,pi,sqrt
atoms=[]
def add(sym,xyz):
 atoms.append((sym,np.array(xyz,float)));return len(atoms)-1
def pix(x,y,z=0): return np.array([(x-171.5)*.0315,(150-y)*.0315,z])
def norm(v):return v/np.linalg.norm(v)
def ch(point,parent,dist=1.09):
 axis=norm(point-parent); t=np.cross(axis,[0,0,1]);
 if np.linalg.norm(t)<.1:t=np.cross(axis,[0,1,0])
 t=norm(t);s=norm(np.cross(axis,t));
 for k in range(3):add('H',point+dist*(axis/3+sqrt(8)/3*(cos(2*pi*k/3)*t+sin(2*pi*k/3)*s)))
# left and right Ir
irL=add('Ir',pix(116,158)); irR=add('Ir',pix(227,158))
# top imidazole ring cycle N(Mes)-CH-CH-N(Ir)-C(Ir)
upper=[add(e,pix(x,y)) for e,x,y in [('N',129,58),('C',168,29),('C',204,56),('N',188,101),('C',143,101)]]
# bottom cycle N(Ir)-CH-CH-N(Mes)-C(Ir)
lower=[add(e,pix(x,y+8)) for e,x,y in [('N',151,201),('C',136,245),('C',173,271),('N',211,244),('C',198,200)]]
# ring hydrogen on CH, radial outward
for ring in (upper,lower):
 ctr=np.mean([atoms[j][1] for j in ring],axis=0)
 for j in (1,2): add('H', atoms[ring[j]][1]+1.08*norm(atoms[ring[j]][1]-ctr))
# ortho,para,ortho trimethylphenyl on upper left and lower right ring N
# mes N-C(ipso) bond has aryl rings twisted out of ring plane
for n,sgn,twist in ((upper[0],-1,.48),(lower[3],1,-.48)):
 pos=atoms[n][1];u=norm(np.array([sgn*.9,sgn*.45,0.]));v=np.array([-u[1]*cos(twist),u[0]*cos(twist),sin(twist)])
 ipso=pos+u*1.44; center=ipso+u*1.40
 ring=[]
 for k in range(6):
  angle=pi+k*pi/3
  ring.append(add('C',center+1.40*(cos(angle)*u+sin(angle)*v)))
 for k in (1,3,5):
  c=atoms[ring[k]][1];m=add('C',c+1.51*norm(c-center));ch(atoms[m][1],c)
 for k in (2,4):
  c=atoms[ring[k]][1];add('H',c+1.08*norm(c-center))
# left methyl and right iodide
me=add('C',atoms[irL][1]+[-2.08,0,0]);ch(atoms[me][1],atoms[irL][1]);i=add('I',atoms[irR][1]+[2.66,0,0])
# carbonyls: hashed left upper is behind the plane, filled right lower is in front
for met,axis in ((irL,[-.64,.62,-.46]),(irR,[.64,-.62,.46])):
 m=atoms[met][1];unit=norm(np.array(axis));c=add('C',m+1.90*unit);o=add('O',m+3.045*unit)
# PMe3: left below-left in front; right upper-right behind
for met,axis in ((irL,[-.47,-.69,.55]),(irR,[.47,.69,-.55])):
 m=atoms[met][1];u=norm(np.array(axis));p=add('P',m+2.28*u);t=norm(np.cross(u,[0,0,1]));s=norm(np.cross(u,t))
 for k in range(3):
  methyl=add('C',atoms[p][1]+1.83*(u/3+sqrt(8)/3*(cos(2*pi*k/3)*t+sin(2*pi*k/3)*s)))
  ch(atoms[methyl][1],atoms[p][1])
with open('answer.xyz','w') as f:
 f.write(f'{len(atoms)}\nDinuclear iridium Mes-imidazolyl complex (explicit hydrogens), initial 3D geometry\n')
 for el,p in atoms:f.write(f'{el:2s} {p[0]: .7f} {p[1]: .7f} {p[2]: .7f}\n')
print('atoms',len(atoms),'indexes',irL,irR,upper,lower, 'Me',me,'I',i)
